metrics.turnover='Traded value';
const previousAmount=amount;amount=function(n,kind='cap'){if(kind==='turnover')return n==null?'—':currency==='INR'?formatINR(n):formatUSD(n/fx);if(feedMode==='kite'&&kind==='price')return n==null?'—':currency==='INR'?formatINR(n,false):formatUSD(n/fx);return previousAmount(n,kind)};
const previousStockPrice=stockPrice;stockPrice=function(s){return feedMode==='kite'?amount(s.price,'price'):previousStockPrice(s)};
function applyKiteQuotes(payload){const byISIN=new Map();for(const q of payload.quotes){if(!byISIN.has(q.isin))byISIN.set(q.isin,[]);byISIN.get(q.isin).push(q)}for(const s of stocks){const match=(byISIN.get(s.isin)||[]).slice().sort((a,b)=>(a.exchange==='NSE'?-1:1))[0],baseline=snapshotStocks.find(b=>b.ticker===s.ticker);s.cap=baseline?.cap??null;s.liveCapEstimated=false;s.liveCapINR=null;s.liveCapBasis='Dated financial-source market cap';s.shares=s.verifiedSharesOutstanding??baseline?.shares??null;s.price=match?.price??s.referencePriceINR??null;s.change=match?.change??null;s.volume=match?.volume??null;s.turnover=match?.turnover??null;s.lastTrade=match?.lastTrade||null;s.instrumentToken=match?.instrumentToken||null;s.liveSource=match?match.exchange:null;s.liveSymbol=match?.symbol||null;if(match||s.referencePriceINR>0){const value=calculateLiveMarketCap({...baseline,ticker:s.verifiedSharesOutstanding&&match?match.symbol+(match.exchange==='NSE'?'.NS':'.BO'):s.ticker,verifiedSharesOutstanding:s.verifiedSharesOutstanding,shareCountDate:s.shareCountDate,shareCountSource:s.shareCountSource},match?.price??s.referencePriceINR,fx);if(value){s.cap=value.capUSD;s.liveCapINR=value.capINR;s.liveCapEstimated=value.estimated;s.liveCapBasis=value.basis+(!match?' · NSE reference close as of '+s.shareCountDate:'')}}}feedStatus=payload.status;feedMode='kite';updateFeedLabel()}
function kiteTopStatus(){const dates=stocks.map(s=>s.lastTrade).filter(Boolean).sort(),latest=dates.at(-1);const fresh=latest&&Date.now()-new Date(latest).getTime()<120000;return fresh&&feedStatus?.connections>0&&marketSession().state==='open'?'Live · Zerodha':latest?'Snapshot · '+new Date(latest).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Kolkata'})+' · Zerodha':'Zerodha · waiting for quotes'}
const previousFeedLabel=updateFeedLabel;updateFeedLabel=function(){if(feedMode!=='kite'){previousFeedLabel();return}$('#feed-state').textContent=kiteTopStatus();$('#feed-state').classList.toggle('feed-connected',$('#feed-state').textContent.startsWith('Live'));$('#currency').disabled=false};
const previousFeedPanel=showFeedPanel;showFeedPanel=function(){if(feedStatus?.provider!=='Zerodha Kite'){previousFeedPanel();return}$('#feed-panel').innerHTML=`<section class="feed-card"><strong>Zerodha Kite · ${feedStatus.authenticated?'Connected account':'Sign-in required'}</strong><p>Official share counts: ${new Set(officialShareRecords.map(r=>r.isin)).size.toLocaleString('en-IN')} companies. ${window.officialShareCoverage?.state==='running'?'Exchange reference refresh is running. ':''}BSE-only gaps remain pending where the official source is unavailable. Market data is read by the local backend. Credentials are never sent to the public website. ${feedStatus.received||0} quotes received; ${feedStatus.subscribed||0} instrument subscriptions. ${feedStatus.unsubscribed?'Some listings exceed Kite’s 9,000-instrument streaming limit.':''}</p><a class="kite-connect-button" href="/api/kite/login">${feedStatus.authenticated?'Reconnect Zerodha':'Connect Zerodha'}</a></section><p class="note">Prices and volume: Zerodha. Financial statements: existing financial source. Market caps use official dated share counts where verified (source details in the value’s hover text). These counts require updates after capital changes. Market caps marked ≈ are price-scaled estimates based on fixed implied shares from dated prices; share-count changes are not known. ADR-based market caps keep their original value. The exchange is currently ${marketSession().state==='open'?'open':'closed'}.</p><p class="note">IPO dates: <a href="https://www.nseindia.com/api/public-past-issues" target="_blank" rel="noopener">NSE history</a>, <a href="https://zerodha.com/ipo/" target="_blank" rel="noopener">Zerodha calendar</a>, <a href="https://ipocentral.in/ipo-2026/" target="_blank" rel="noopener">IPO Central</a>. Reviewed BSE notices: ${reviewedShareRecords.map(r=>`<a href="${r.source}" target="_blank" rel="noopener">${escapeHtml(r.name)}</a>`).join(', ')}. Kite login sessions expire daily. Reconnect when prompted. No order-placement functionality is used.</p>`};
function markEstimatedCaps(){document.querySelectorAll('.ranking-table tbody tr').forEach(row=>{const button=row.querySelector('[data-company]'),s=stocks.find(s=>s.rank===Number(button?.dataset.company));if(s?.cap!=null&&metric==='cap'){const cell=row.querySelector('td.number');if(cell){cell.title=s.liveCapBasis||'Dated financial-source market cap';cell.innerHTML=(s.liveCapEstimated?'<span class="estimate-mark">≈</span> ':'')+amount(s.cap);if(s.shareCountSource&&!s.liveCapEstimated)cell.title+=' · '+s.verifiedSharesOutstanding.toLocaleString('en-IN')+' shares · '+(s.shareCountSourceTitle||'Official exchange reference')}}});}
const previousRenderRows=renderRows;renderRows=function(){previousRenderRows();markEstimatedCaps()};
function refreshKiteView(){const table=$('.ranking-table'),scroll=table?{top:table.scrollTop,left:table.scrollLeft}:null;if(['rankings','watchlist'].includes(tab)){updateStats();renderRows();if(scroll){const next=$('.ranking-table');next.scrollTop=scroll.top;next.scrollLeft=scroll.left}}else if(tab==='stock'){const ticker=decodeURIComponent(location.hash.split('/')[1]||''),s=stocks.find(s=>s.ticker===ticker);if(s){const cards=document.querySelectorAll('.stock-overview strong');if(cards[0]){cards[0].textContent=(s.liveCapEstimated?'≈ ':'')+amount(s.cap);cards[0].title=s.liveCapBasis||''}if(cards[1])cards[1].textContent=stockPrice(s);if(cards[2])cards[2].innerHTML=changeBadge(s)}}else if(tab==='compare'){const selected=compare.map(t=>stocks.find(s=>s.ticker===t)).filter(Boolean),keys=Object.keys(metrics);document.querySelectorAll('.compare-table tbody tr').forEach((row,i)=>{const key=keys[i]||'price';selected.forEach((s,j)=>{if(row.cells[j+1])row.cells[j+1].textContent=key==='price'?stockPrice(s):amount(s[key],key)})})}else if(tab==='charts'){if(document.querySelector('.stock-treemap:hover,.scatter-stage:hover,.chart-bar-list:hover,.donut-wrap:hover,.sector-chart-legend:hover')||document.activeElement?.closest('.charts-workspace'))return;renderCharts()}else render()}
let kiteCompareRange='1M',kiteStockRange='1M',kiteChartRequest=0;
const priceHistoryRequests=new Map();
async function getPriceHistory(s,range){const key=s.instrumentToken+':'+range;if(!priceHistoryRequests.has(key)){const request=fetch('/api/kite/history?'+new URLSearchParams({token:s.instrumentToken,range})).then(async response=>{const data=await response.json();if(!response.ok)throw Error(data.error||'History unavailable');return data});priceHistoryRequests.set(key,request);setTimeout(()=>priceHistoryRequests.delete(key),60000);request.catch(()=>priceHistoryRequests.delete(key))}return priceHistoryRequests.get(key)}
async function loadKiteComparison(selected,range=kiteCompareRange,target=null){
 const stockChart=Boolean(target),card=target||document.querySelector('.compare-overlay');if(!card)return;card.dataset.chartTitle=stockChart?'Price history · '+selected[0].name:'Price performance';const request=++kiteChartRequest,comparison=!stockChart;
 card.innerHTML=`<div class="overlay-heading"><h3>${comparison?'Price performance':'Price history'}</h3><span class="chart-unit-label">${comparison?'Change (%)':currency}</span></div>${chartTimelineControls('data-kite-range',range,CHART_TIMELINES)}<div class="kite-history-content" aria-busy="true"><p class="note chart-loading" role="status">Loading price history…</p></div>`;
 card.querySelectorAll('[data-kite-range]').forEach(button=>button.onclick=()=>{if(stockChart)kiteStockRange=button.dataset.kiteRange;else kiteCompareRange=button.dataset.kiteRange;loadKiteComparison(selected,button.dataset.kiteRange,target)});
 const palette=['#397de0','#b57100','#168163','#a24bd0'];
 const values=await Promise.all(selected.map(async(s,i)=>{if(!s.instrumentToken)return {s,error:'No historical instrument is available.'};try{return {s,color:palette[i],dash:['','6 3','2 3','8 3 2 3'][i],data:await getPriceHistory(s,range)}}catch(error){return {s,error:error.message}}}));
 if(request!==kiteChartRequest||!document.contains(card))return;const holder=card.querySelector('.kite-history-content');holder.setAttribute('aria-busy','false');const good=values.filter(v=>v.data?.points.length>1),errors=values.filter(v=>!v.data?.points.length||v.data.points.length<2);
 if(!good.length){holder.innerHTML='<div class="chart-empty"><strong>Price history unavailable</strong><p>Try another period or reconnect Zerodha from Data sources.</p></div>';return}
 const series=preparePriceSeries(good.map(v=>({name:v.s.name,ticker:v.s.ticker,color:v.color,dash:v.dash,points:v.data.points})),{comparison});if(series.some(s=>s.points.length<2)){holder.innerHTML='<div class="chart-empty"><strong>No shared observations</strong><p>These companies have no matching trading observations in this period. Try a longer period.</p></div>';return}
 const displayAxisPrice=p=>currency==='INR'?formatINR(p,false):formatUSD(p),displayPrice=p=>displayAxisPrice(currency==='INR'?p:p/fx),percent=v=>(v>0?'+':'')+v.toFixed(2)+'%';
 for(const s of series){if(!comparison&&currency==='USD')for(const p of s.points)p.value/=fx;s.format=comparison?percent:displayAxisPrice;s.formatPrice=displayPrice;s.difference=(a,b,pa,pb)=>{const pct=(pb.price/pa.price-1)*100,delta=pb.price-pa.price;return (delta>=0?'+':'−')+displayPrice(Math.abs(delta))+' ('+percent(pct)+')'};for(const p of s.points)p.label=chartTimeLabel(p.time,range,true)}
 holder.innerHTML=`<div class="chart-summary" aria-live="polite"></div><div class="price-chart-canvas"></div><div class="overlay-legend"></div><p class="note chart-history-note">${comparison?'All lines start at 0% on the same shared observation. ':''}Zerodha${selected.length===1&&selected[0].liveSymbol?' · '+escapeHtml(selected[0].liveSource+':'+selected[0].liveSymbol):''} · ${range==='1D'||range==='5D'?'5-minute prices · trading sessions only':'Daily prices · trading sessions only'}${range==='MAX'?' · Provider window: up to 20 years':''}. ${series[0].points.length.toLocaleString()} observations per line.</p>${errors.map(v=>`<p class="chart-data-warning">${escapeHtml(v.s.name)}: ${escapeHtml(v.error||'Insufficient history for this period.')}</p>`).join('')}`;
 const summary=holder.querySelector('.chart-summary'),last=series[0].points.at(-1);if(['1D','5D'].includes(range)){const date=new Date(last.time),minute=(date.getUTCHours()*60+date.getUTCMinutes()+330)%1440;if(minute<925&&last.time.slice(0,10)<new Date().toISOString().slice(0,10)){const note=document.createElement('p');note.className='chart-coverage-note';note.textContent='Provider history ends before this session’s closing candle. The latest quote may be newer.';holder.querySelector('.chart-history-note').after(note)}}summary.textContent=chartTimeLabel(series[0].points[0].time,range,true)+' — '+chartTimeLabel(last.time,range,true);
 const legend=holder.querySelector('.overlay-legend');series.forEach((s,i)=>{const button=document.createElement('button');button.className='overlay-toggle';button.dataset.seriesDash=s.dash||'none';button.setAttribute('aria-pressed','true');button.innerHTML=`<i style="border-top:2px ${s.dash==='2 3'?'dotted':s.dash?'dashed':'solid'} ${s.color};background:transparent"></i><span>${escapeHtml(s.name)}</span><b>${comparison?percent(s.points.at(-1).value):displayPrice(s.points.at(-1).price)}</b>`;button.onclick=()=>{const active=button.getAttribute('aria-pressed')!=='true';if(!active&&series.filter(s=>!s.hidden).length===1)return;s.hidden=!active;button.setAttribute('aria-pressed',String(active));draw()};legend.append(button)});
 const canvas=holder.querySelector('.price-chart-canvas');let drawnWidth=0;
 function draw(){if(!canvas.isConnected)return;const visible=series.filter(s=>!s.hidden),width=Math.max(280,Math.round(canvas.clientWidth||800)),height=width<500?285:330,left=width<500?65:78,right=18,top=28,bottom=height-46,plot=width-left-right,points=visible[0].points,scale=niceChartScale(visible.flatMap(s=>s.points.map(p=>p.value)),{includeZero:comparison,count:5});
 for(const s of visible)for(let i=0;i<s.points.length;i++){const p=s.points[i];p.x=left+i/(s.points.length-1)*plot;p.y=bottom-(p.value-scale.min)/(scale.max-scale.min)*(bottom-top)}
 drawnWidth=width;const ticks=chartObservationTicks(points,range,width),axis=v=>comparison?(Math.abs(v)<1e-8?'0%':v.toLocaleString('en-IN',{maximumFractionDigits:2})+'%'):(currency==='INR'?formatINR(v):formatUSD(v)),zero=bottom-(0-scale.min)/(scale.max-scale.min)*(bottom-top);
 canvas.innerHTML=`<svg class="overlay-chart price-history-chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="${comparison?'Comparable price performance':'Share price in '+currency} from ${escapeHtml(points[0].label)} to ${escapeHtml(points.at(-1).label)}"><text class="chart-axis-unit" x="${left}" y="15">${comparison?'Change (%)':currency+' price'}</text>${scale.ticks.map(v=>{const y=bottom-(v-scale.min)/(scale.max-scale.min)*(bottom-top);return `<line class="chart-gridline" x1="${left}" x2="${width-right}" y1="${y}" y2="${y}"/><text x="${left-10}" y="${y+4}" text-anchor="end">${escapeHtml(axis(v))}</text>`}).join('')}${comparison?`<line class="chart-zero-line" x1="${left}" x2="${width-right}" y1="${zero}" y2="${zero}"/>`:''}${ticks.map((t,i)=>{const x=left+t.index/(points.length-1)*plot;return `<line class="chart-axis-tick" x1="${x}" x2="${x}" y1="${bottom}" y2="${bottom+5}"/><text x="${x}" y="${bottom+23}" text-anchor="${i===0?'start':i===ticks.length-1?'end':'middle'}">${escapeHtml(t.label)}</text>`}).join('')}${visible.map(s=>`<path class="overlay-series" d="${s.points.map((p,i)=>(i?'L':'M')+p.x.toFixed(2)+','+p.y.toFixed(2)).join(' ')}" fill="none" stroke="${s.color}" stroke-dasharray="${s.dash||'none'}"/>`).join('')}<text class="chart-timezone" x="${width-right}" y="${height-3}" text-anchor="end">${range==='1D'?'Time (IST)':'Trading dates (IST)'}</text></svg>`;
 attachChartInteraction(canvas.querySelector('svg'),visible,{left,right:width-right,top,bottom});}
 draw();const observer=new ResizeObserver(()=>{if(!canvas.isConnected){observer.disconnect();return}if(Math.max(280,Math.round(canvas.clientWidth))!==drawnWidth)draw()});observer.observe(canvas);
}
const previousRenderCompare=renderCompare;renderCompare=function(){previousRenderCompare();if(feedMode==='kite'){const selected=compare.map(t=>stocks.find(s=>s.ticker===t)).filter(Boolean);if(selected.length)loadKiteComparison(selected)}};

const previousCompanyMetric=renderCompanyMetric;renderCompanyMetric=function(s,key){previousCompanyMetric(s,key);if(feedMode==='kite'&&key==='price'&&s.instrumentToken){const target=document.querySelector('.stock-chart-card');if(target)loadKiteComparison([s],kiteStockRange,target)}if(feedMode==='kite'&&s.liveCapEstimated){const value=document.querySelector('.stock-overview strong');if(value){value.textContent='≈ '+amount(s.cap);value.title=s.liveCapBasis}if(key==='cap'){const current=document.querySelector('.stock-current>strong');if(current){current.textContent='≈ '+amount(s.cap);current.title=s.liveCapBasis}}}};

async function refreshOfficialShareData(){
 if(document.hidden||!stocks.length)return;
 try{const response=await fetch('official-shares.json',{cache:'no-store'});if(!response.ok)return;const data=await response.json();const ipoResponse=await fetch('ipo-listings.json',{cache:'no-store'});if(ipoResponse.ok){const ipos=await ipoResponse.json();officialIPORecords=[...supplementalIPORecords,...(ipos.records||[])];attachIPOListings(stocks,officialIPORecords)}const signature=JSON.stringify(data.records);if(signature===window.officialSharesSignature)return;window.officialSharesSignature=signature;officialShareRecords=[...(data.records||[]),...reviewedShareRecords];window.officialShareCoverage=data.coverage;attachOfficialShares(stocks,officialShareRecords);if(feedMode==='kite'){const payload=await readFeed();if(payload?.status?.authenticated){applyKiteQuotes(payload);refreshKiteView()}}else if(['rankings','watchlist'].includes(tab))renderRows()}catch{}
}
setInterval(refreshOfficialShareData,30000);

function revalueNativeCaps(){if(feedMode==='kite')for(const s of stocks)if(Number.isFinite(s.liveCapINR))s.cap=s.liveCapINR/fx/1e9}
